# Generated by Claudian.
"""Skill: search files/folders on the Mac via Spotlight."""

import re

from ai.response_generator import ResponseGenerator
from automation.file_search import search_local
from multitasking.async_executor import run_in_thread
from skills._base import Skill, SkillMatch, SkillResult

_PATTERNS = [
    re.compile(
        r"(?:find|search\s+for|look\s+for|locate)\s+(.+?)"
        r"\s+(?:on\s+my\s+(?:mac|computer|laptop)|locally)"
    ),
    re.compile(
        r"(?:find|search\s+for|look\s+for)\s+(?:the\s+)?"
        r"(?:file|folder|document|application)\s+(.+)"
    ),
]


class SearchLocalSkill(Skill):
    name = "search_local"
    description = "Search for a file or folder on the Mac"
    priority = 20

    def __init__(self):
        self._responses = ResponseGenerator()

    def match(self, text: str) -> SkillMatch | None:
        low = text.lower()
        for pat in _PATTERNS:
            m = pat.search(low)
            if m:
                return SkillMatch(confidence=0.9, entities={"query": m.group(1).strip()})
        return None

    async def run(self, text: str, entities: dict) -> SkillResult:
        query = entities.get("query", text)
        results = await run_in_thread(search_local, query)
        return SkillResult(text=self._responses.search_results(query, results))
